style.css:
@-moz-document domain("web.max.ru") {
/* --- Основной фон приложения --- */
    body,
    html,
    #app,
    [class*="App"],
    [class*="Layout"],
    [class*="Main"],
    [class*="Root"],
    [class*="Page"] {
        background-image: url('https://avatars.mds.yandex.net/get-vertis-journal/4469561/78f0e6fa-d23c-4773-9068-30b7969a19c1.jpg/1600x1600') !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    /* --- Прозрачность для областей чатов и сайдбара --- */
    [class*="ChatList"],
    [class*="Sidebar"],
    [class*="ChatWindow"],
    [class*="MessageList"],
    [class*="Dialog"],
    [class*="Conversation"],
    [class*="Content"],
    [class*="MainContent"] {
        background-color: transparent !important;
        background-image: none !important;
    }

    /* --- Полупрозрачные панели с размытием --- */
    [class*="Header"],
    [class*="Footer"],
    [class*="Panel"],
    [class*="Toolbar"],
    [class*="Navbar"],
    [class*="TopBar"],
    [class*="BottomBar"],
    [class*="InputBar"] {
        background-color: rgba(0, 0, 0, 0.45) !important;
        backdrop-filter: blur(6px) !important;
        -webkit-backdrop-filter: blur(6px) !important;
    }
}
